1	export interface Scenario {
2	  customer: { yearsWithMHPCO: number };
3	  steps: Step[];
4	}
5	
6	export type Step = QuoteStep | ClaimStep;
7	
8	export interface QuoteStep {
9	  op: "quote";
10	  items: Item[];
11	}
12	
13	export interface Item {
14	  type: string;
15	  material?: string;
16	  enchantment?: number;
17	  cursed?: boolean;
18	}
19	
20	export interface ClaimStep {
21	  op: "claim";
22	  policy: number;
23	  incident: Incident;
24	}
25	
26	export interface Incident {
27	  cause: string;
28	  damages: Damage[];
29	}
30	
31	export interface Damage {
32	  itemType: string;
33	  amount: number;
34	}
35	
36	export type Result = { premium: number } | { payout: number; remainingCap: number };
37	
38	const PROCESSING_FEE = 5;
39	
40	const FIRST_INSURANCE_SURCHARGE = 0.1;
41	
42	/** Rounds up in the MHPCO's favor, ignoring binary floating-point noise. */
43	const roundPremium = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
44	
45	const BASE_PREMIUMS: Record<string, number> = {
46	  sword: 100,
47	  amulet: 60,
48	  staff: 80,
49	};
50	
51	const quotePremium = (items: Item[]): number => {
52	  const basePremium = items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
53	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE;
54	  return roundPremium(basePremium + firstInsuranceSurcharge + PROCESSING_FEE);
55	};
56	
57	const runStep = (step: Step): Result => {
58	  if (step.op === "quote") return { premium: quotePremium(step.items) };
59	  throw new Error(`Unsupported step: ${step.op}`);
60	};
61	
62	export const runScenario = (scenario: Scenario): { results: Result[] } => {
63	  return { results: scenario.steps.map(runStep) };
64	};
